Getting the data
The data is downloaded by code from data.gouv.fr, using the stable resource links of the dataset Arbres urbains published by the town of Saint-Germain-en-Laye. A file is only downloaded if it is not already in data/raw/, so re-rendering the book does not hit the network and always uses the same copy.


Show code
eda_sources &lt;- c(
  "arbres-urbains.csv"         = "https://www.data.gouv.fr/api/1/datasets/r/96f4164d-956d-4c1c-b161-68724eb0ccdc",
  "arbres-urbains.geojson"     = "https://www.data.gouv.fr/api/1/datasets/r/13add5f3-d3db-407a-8a72-a069379a2e44",
  "arbres-urbains_legende.pdf" = "https://www.data.gouv.fr/api/1/datasets/r/feced38e-ca55-43a0-983b-6db0e2632c02"
)

dir.create(here("data", "raw"), recursive = TRUE, showWarnings = FALSE)
for (f in names(eda_sources)) {
  dest &lt;- here("data", "raw", f)
  if (!file.exists(dest)) download.file(eda_sources[[f]], dest, mode = "wb", quiet = TRUE)
}

Act 4 · Who’s to blame?


Show code
cause_cols &lt;- c("External", "Infrastructure", "Traffic management",
                "Rolling stock", "Station management", "Passengers")
groups &lt;- c(External = "External", Infrastructure = "Tracks",
            `Traffic management` = "Tracks", `Rolling stock` = "Trains",
            `Station management` = "Trains", Passengers = "Passengers")

causes &lt;- routes |&gt;
  filter(year %in% 2018:2025, rowSums(across(all_of(cause_cols))) &gt; 0) |&gt;
  pivot_longer(all_of(cause_cols), names_to = "cause", values_to = "share") |&gt;
  mutate(group = factor(groups[cause], levels = c("Tracks", "Trains", "External", "Passengers")),
         late_trains = share / 100 * late)

cause_total &lt;- causes |&gt;
  group_by(group) |&gt;
  summarise(n = sum(late_trains), .groups = "drop") |&gt;
  mutate(pct = 100 * n / sum(n))
pct_of &lt;- \(g) number(cause_total$pct[cause_total$group == g], accuracy = 1)




Show code
causes |&gt;
  group_by(year, group) |&gt;
  summarise(n = sum(late_trains), .groups = "drop") |&gt;
  group_by(year) |&gt;
  mutate(pct = n / sum(n)) |&gt;
  ggplot(aes(factor(year), pct, fill = fct_rev(group))) +
  geom_col(width = .75, colour = "white", linewidth = .4) +
  scale_fill_manual(values = c(Tracks = "#D55E00", Trains = "#0072B2",
                               External = "#009E73", Passengers = "#CC79A7"),
                    breaks = c("Tracks", "Trains", "External", "Passengers")) +
  scale_y_continuous(labels = label_percent(), expand = c(0, 0)) +
  labs(x = NULL, y = "Share of late trains", fill = NULL)








Figure 5.4: Delay causes as attributed by SNCF, weighted by the number of late trains (2018–2025). Okabe-Ito colour-blind-safe palette.





Mostly the tracks (Figure 5.4). Weighted by late trains, tracks (infrastructure + traffic management) account for 44 % of delays, trains (rolling stock + station management) 27 %, external causes 21 % and passengers 8 %. Two caveats: SNCF attributes the causes itself, and the “tracks first” result depends on our grouping, since no single SNCF category dominates on its own.
